'use strict';
state=MossSystems.clean(state);
const garden=worlds.valley;
for(let i=0;i<6;i++){const x=24+i%3*2,y=23+Math.floor(i/3)*2;garden.tiles[y][x]='soil';garden.objects.push({id:'garden-'+i,type:'plot',plot:String(i),x:x*T+16,y:y*T+16});}
const bondDescriptions={Pip:'Level 2: +1 berry per pick',Emberkin:'Level 2: +1 wood per chop',Dewdrop:'Level 2: +1 fish per catch',Lunamoth:'Level 2: +1 crystal per vein'};
const lifeAccrue=accrue;accrue=function(now=Date.now()){const dt=lifeAccrue(now);state.life.elapsed+=dt/1000;return dt;};
const lifeComplete=completeActivity;completeActivity=function(){if(!activity)return;const type=activity.o.type,n=state.life.active,before=MossSystems.level(state,n),r=resourceInfo[type];const bonus=state.life.tools+((({berries:'Pip',log:'Emberkin',fish:'Dewdrop',crystals:'Lunamoth'})[type]===n&&before>=2)?1:0);state[r.item]+=bonus;state.life.bond[n]=Math.min(900,state.life.bond[n]+12);lifeComplete();if(MossSystems.level(state,n)>before){GameAudio.sfx('success');toast(n+' reached level '+MossSystems.level(state,n)+'! '+bondDescriptions[n]);}save();};
// The selected companion follows physically as well as receiving gathering XP.
const lifeCreature=creature;creature=function(x,y,name,walk){lifeCreature(x,y,name==='Pip'?state.life.active:name,walk);};
const lifeNearest=nearest;nearest=function(){let best=lifeNearest(),d=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>o.type==='plot')){const n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){best=o;d=n;}}return best;};
function plotMenu(id){const p=state.life.plots[id],growth=MossSystems.grow(p),remaining=p?Math.max(0,Math.ceil((MossSystems.crops[p.crop].seconds*(p.watered?.65:1))-(Date.now()-p.planted)/1000)):0;show(p?MossSystems.crops[p.crop].name:'A little patch of possibility',p?`<p>${growth>=1?'Ready to harvest!':`${Math.floor(growth*100)}% grown · about ${remaining}s left`}</p><p>${p.watered?'Watered — growing faster.':'Water this crop to shorten its growing time.'} Crops grow while you are away.</p><div class="actions"><button data-life="harvest" data-id="${id}" ${growth<1?'disabled':''}>${gameIcon('seed')}Harvest</button><button data-life="water" data-id="${id}" ${p.watered?'disabled':''}>${gameIcon('fish')}Water</button><button data-life="plot" data-id="${id}">${gameIcon('hand')}Check growth</button></div>`:`<p>Plant a seed, water it, then come back to harvest ingredients for your workbench.</p><div class="actions"><button data-life="plant" data-id="${id}" data-crop="turnip" ${state.life.seeds<1?'disabled':''}>${gameIcon('seed')}Sun turnip · 90s (${state.life.seeds} seeds)</button><button data-life="plant" data-id="${id}" data-crop="moonbean" ${state.life.moonSeeds<1?'disabled':''}>${gameIcon('seed')}Moon bean · 3m (${state.life.moonSeeds} seeds)</button></div>`,'Homestead garden');}
const lifeInteract=interact;interact=function(){if(SaveStore.status().blocked){saveMenu();return;}if(!dialog&&!activity&&nearest()?.type==='plot'){faceTarget(nearest());plotMenu(nearest().plot);return;}lifeInteract();};
const lifeObject=object;object=function(o){if(o.type!=='plot'){lifeObject(o);return;}const p=state.life.plots[o.plot],g=MossSystems.grow(p);rr(o.x-13,o.y-10,26,22,p?.watered?'#654b3d':'#9b704d');for(let i=0;i<3;i++)rr(o.x-11,o.y-7+i*7,22,2,'#473d32');if(p){for(const dx of [-7,0,7]){rr(o.x+dx,o.y-4-g*10,2,9+g*7,'#6c9851');rr(o.x+dx-3,o.y-6-g*9,8,4,'#a0bd67');if(g>=1){rr(o.x+dx-2,o.y-4,6,7,p.crop==='turnip'?'#f0d69d':'#bbb0de');}}if(g>=1)text('✦',o.x,o.y-23,'#ffe8a2',10);}else text('+',o.x,o.y+3,'#d8ba83',11);};
const lifeHUD=interactionHUD;interactionHUD=function(){lifeHUD();if(near?.type==='plot'&&!activity){document.getElementById('action').innerHTML='Garden<small>E / A</small>';document.getElementById('action').setAttribute('aria-label','Tend garden bed');document.getElementById('near').textContent=state.life.plots[near.plot]?'Your growing crop':'Empty garden bed';}};
function adventureMenu(){show('A home worth coming back to',`<p>Follow the first adventure at your own pace. Collect each chapter reward here.</p>${MossSystems.chapters.map(([title,desc,test,coins],i)=>{const done=state.life.claimed.includes(i);return `<div class="chapter card ${done?'done':''}"><div class="card-icon">${done?gameIcon('check'):gameIcon('tasks')}</div><div class="card-body"><small>CHAPTER ${i+1} · ${gameIcon('coins')}${coins}</small><b>${title}</b><p>${desc}</p>${done?'<span class="badge-done">'+gameIcon('check')+'Complete</span>':`<button data-life="claim" data-id="${i}" ${!test(state)||i>0&&!state.life.claimed.includes(i-1)?'disabled':''}>${test(state)?'Collect reward':'In progress'}</button>`}</div></div>`;}).join('')}<div class="actions"><button data-extra="journal">${gameIcon('map')}World guide</button><button data-ui="close">${gameIcon('boot')}Back to the trail</button></div>`,'Adventure journal');}
const lifeQuest=questText;questText=function(){const i=MossSystems.chapters.findIndex((_,i)=>!state.life.claimed.includes(i));if(i<0)return 'The valley is home. Grow, craft and explore.';const c=MossSystems.chapters[i];return c[2](state)?`${c[0]} · claim your reward in Journal`:`${i+1}/8 · ${c[1]}`;};
function companionMenu(){show('Small friends, big adventures',`<p>Your travelling companion earns 12 bond XP whenever you gather. Treats give 50 XP. Every 100 XP earns a level, up to 10.</p>${state.team.map(n=>`<div class="chapter card"><div class="card-icon">${gameIcon('friends')}</div><div class="card-body"><b>${n} · level ${MossSystems.level(state,n)} ${state.life.active===n?'· travelling':''}</b><p>${state.life.bond[n]}/900 bond XP<br>${bondDescriptions[n]}</p><div class="health"><div style="width:${MossSystems.level(state,n)===10?100:state.life.bond[n]%100}%"></div></div><div class="actions"><button data-life="follow" data-name="${n}" ${state.life.active===n?'disabled':''}>${gameIcon('boot')}Travel together</button><button data-life="feed" data-name="${n}" ${state.life.treats<1||MossSystems.level(state,n)===10?'disabled':''}>${gameIcon('berries')}Give treat (${state.life.treats})</button></div></div></div>`).join('')}<div class="actions"><button data-ui="bag">${gameIcon('bag')}Gathering jobs</button><button data-ui="close">${gameIcon('hand')}Let's go</button></div>`,'Companions');}
const campUpgrade=upgradeDialog;upgradeDialog=function(){show('Make something useful',`<p>Turnips ${state.life.turnips} · Moon beans ${state.life.moonbeans} · Treats ${state.life.treats}</p>${Object.entries(MossSystems.recipes).map(([id,r])=>{const owned=['tools','lantern'].includes(r.item)&&state.life[r.item];return `<div class="chapter card"><div class="card-icon">${gameIcon(id==='tool'?'tool':id==='lantern'?'hand':'seed')}</div><div class="card-body"><b>${r.name}${owned?' · owned':''}</b><p>${Object.entries(r.cost).map(([k,n])=>`${n} ${k}`).join(' + ')}${id==='tool'?'<br>+1 item from every gathering action.':id==='lantern'?'<br>A warm pool of light after sunset.':''}</p><button data-life="craft" data-id="${id}" ${owned||!Object.entries(r.cost).every(([k,v])=>(k in state.life?state.life[k]:state[k])>=v)?'disabled':''}>Craft</button></div></div>`;}).join('')}<div class="actions"><button data-life="upgrade">${gameIcon('home')}Improve camp</button><button data-ui="close">${gameIcon('boot')}Leave workbench</button></div>`,'Homestead workshop');};
const lifeBag=bag;bag=function(){lifeBag();const d=document.querySelector('.dialog');const nav=document.createElement('div');nav.className='actions';nav.innerHTML=`<button data-life="companions">${gameIcon('friends')}Companions & levels</button><button data-life="journal">${gameIcon('tasks')}Adventure journal</button><button data-life="saves">${gameIcon('bag')}Saves & backup</button>`;d.append(nav);};
const lifeHelp=help;help=function(){lifeHelp();const d=document.createElement('div');d.className='actions';d.innerHTML=`<button data-life="journal">${gameIcon('tasks')}Adventure journal</button><button data-life="companions">${gameIcon('friends')}Companions</button><button data-life="saves">${gameIcon('bag')}Saves & backup</button>`;document.querySelector('.dialog').append(d);};
function valleyTime(){const day=Math.floor(state.life.elapsed/720),hour=Math.floor(((state.life.elapsed/720+.25)%1)*24);return {day:day+1,hour,night:hour>=19||hour<6,rain:day%3===1};}
const lifeDraw=draw;draw=function(){lifeDraw();if(map.inside)return;const {night,rain}=valleyTime();if(night){ctx.fillStyle='#17273b66';ctx.fillRect(0,0,W,H);if(state.life.lantern){const x=player.x-camera.x,y=player.y-camera.y;ctx.fillStyle='#f2d89322';ctx.beginPath();ctx.arc(x,y,60,0,Math.PI*2);ctx.fill();}for(let i=0;i<10;i++)rr((i*97+Math.sin(clockTime+i)*10)%W,(i*61+Math.cos(clockTime+i)*8)%H,2,2,'#e4d994');}if(rain){ctx.fillStyle='#668ba322';ctx.fillRect(0,0,W,H);for(let i=0;i<45;i++)rr((i*59+clockTime*17)%W,(i*83+clockTime*130)%H,1,7,'#c4d6d966');}};
const lifeHud=hud;hud=function(){lifeHud();const d=document.getElementById('day'),time=valleyTime();d.textContent=time.day;if(d.parentElement?.firstChild)d.parentElement.firstChild.textContent=(time.rain?'☂ Rain':time.night?'☾ Night':'☀ Spring')+', day ';renderSaveBadge();};
const lifeTick=tickActivities;tickActivities=function(dt){lifeTick(dt);if(!state.life.visits.includes(map.id))state.life.visits.push(map.id);if(SaveStore.status().blocked)resetInput();const time=valleyTime();if(time.rain)for(const p of Object.values(state.life.plots))p.watered=true;for(const n of map.npcs.filter(n=>n.kind==='human')){if(!dialog&&Math.hypot(n.x-player.x,n.y-player.y)>58){const target=n.name==='Mara'?(time.night?[6,10]:time.hour<12?[6,5]:[8,8]):time.rain||time.night?[20,19]:time.hour<12?[27,18]:[27,23];move(map,n,(target[0]*T+16-n.x)*Math.min(dt*.5,1),(target[1]*T+16-n.y)*Math.min(dt*.5,1));}}};
const livingShow=show;show=function(title,body,kicker){if(title==='Mara'){const time=valleyTime();body+='<p><i>'+ (time.night?'“The fire is warm. Tomorrow, try planting something in the garden south of your homestead.”':!state.life.harvested?'“Those six empty garden beds are yours. You have seeds already. Water them, and they’ll be ready sooner.”':!state.life.treatsMade?'“Two sun turnips and two berries make a fine friendship treat. Your workbench has the recipe.”':'“Your friends learn by travelling with you. Choose a companion in your bag and take them gathering.”')+'</i></p>';}if(title==='Nell, the river fisher')body+='<p><i>'+ (valleyTime().rain?'Nell has moved closer to camp to shelter from the rain.':valleyTime().night?'Nell rests by camp as the river darkens.':'Nell follows the fish downstream after midday.')+'</i></p>';livingShow(title,body,kicker);};
function renderSaveBadge(){const b=document.getElementById('save-status');if(!b)return;const s=SaveStore.status();b.textContent=s.problem?'Save issue':s.conflict?'Review saves':s.cloud.startsWith('Cloud saved')?'Saved ☁':'Saved on device';b.setAttribute('aria-label',s.problem||s.cloud);}
function escapeSave(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function saveMenu(){const s=SaveStore.status(),remote=s.conflict?.save;show('Keep your adventure safe',`<p role="status">${escapeSave(s.problem||'Autosaves on this device every few seconds.')}<br>${escapeSave(s.cloud)}</p>${s.conflict?`<div class="chapter"><b>Two adventures need a choice</b><p>Device: ${state.team.length} friends · ${state.coins} coins<br>Cloud: ${remote?`${remote.team?.length||1} friends · ${remote.coins||0} coins`:'No adventure on this account'}<br>Continuing on this device will replace the cloud copy. Download a backup first if you want to keep both.</p><div class="actions"><button data-life="usecloud" ${remote?'':'disabled'}>Continue cloud adventure</button><button data-life="usedevice">Keep this device's adventure</button></div></div>`:''}<div class="actions">${s.cloudAvailable?'<button data-life="sync">Back up to cloud now</button>':''}<button data-life="export">Download backup</button><button data-life="import">Restore a backup</button><button data-life="recovery">Recover previous save</button>${s.blocked?'<button data-life="reload">Reload this tab</button>':''}</div><p>${s.cloudAvailable?'Cloud backup follows your signed-in account when connected.':'This version saves on this device. Download a backup to transfer your adventure to another browser or address.'} Away gathering is capped at 8 hours.</p><input id="save-import" type="file" accept="application/json,.json" hidden><div class="actions"><button data-ui="close">Back to playing</button></div>`,'Saves & recovery');}
let pendingImport=null;
app.addEventListener('change',async e=>{if(e.target.id!=='save-import')return;const f=e.target.files?.[0];if(!f)return;try{if(f.size>100000)throw Error('That file is too large for a Mosswild save.');pendingImport=MossSystems.unpack(await f.text());show('Restore this adventure?',`<p>${pendingImport.team.length} companions · ${pendingImport.coins} coins. This replaces the adventure on this device. A copy of your current adventure is kept under Recover previous save.</p><div class="actions"><button data-life="confirmimport">Restore adventure</button><button data-life="saves">Cancel</button></div>`,'Backup found');}catch(error){toast(error.message);}});
app.addEventListener('click',async e=>{const b=e.target.closest('[data-life]');if(!b||b.disabled)return;const a=b.dataset.life,id=b.dataset.id,n=b.dataset.name;
 if(a==='saves'){saveMenu();return;}if(a==='reload'){location.reload();return;}if(a==='export'){const blob=new Blob([SaveStore.status().blocked?(SaveStore.raw()||JSON.stringify({schema:2,state})):JSON.stringify({schema:2,savedAt:Date.now(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='mosswild-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(a==='recovery'){try{pendingImport=SaveStore.recovery();show('Recover this adventure?',`<p>${pendingImport.team.length} companions · ${pendingImport.coins} coins. Restore the previous device copy? Cloud backup will ask you to choose before replacing anything.</p><div class="actions"><button data-life="confirmimport">Restore adventure</button><button data-life="saves">Cancel</button></div>`,'Local recovery');}catch{toast('No readable recovery copy is available yet.');}return;}if(a==='import'){document.getElementById('save-import').click();return;}if(a==='confirmimport'&&pendingImport){if(SaveStore.replace(pendingImport))location.reload();else toast(SaveStore.status().problem);return;}if(a==='sync'){await SaveStore.sync(true);saveMenu();return;}if(a==='usecloud'||a==='usedevice'){await SaveStore.choose(a==='usecloud'?'cloud':'device');saveMenu();return;}
 if(SaveStore.status().blocked){saveMenu();return;}
 if(a==='journal')adventureMenu();else if(a==='companions')companionMenu();else if(a==='claim'){if(MossSystems.claim(state,Number(id))){GameAudio.sfx('success');toast('Chapter complete! Your reward is in your bag.');}adventureMenu();}else if(a==='follow'&&state.team.includes(n)){state.life.active=n;companionMenu();}else if(a==='feed'&&state.team.includes(n)&&state.life.treats>0&&MossSystems.level(state,n)<10){state.life.treats--;state.life.bond[n]=Math.min(900,state.life.bond[n]+50);GameAudio.sfx('success');companionMenu();}else if(a==='upgrade')campUpgrade();else if(a==='craft'&&map.id==='home'&&nearest()?.type==='workbench'){if(MossSystems.craft(state,id)){GameAudio.sfx('success');toast('Made '+MossSystems.recipes[id].name+'!');}upgradeDialog();}else if(['plant','water','harvest','plot'].includes(a)&&nearest()?.type==='plot'&&nearest().plot===id){if(a==='plant')MossSystems.plant(state,id,b.dataset.crop);if(a==='water'&&state.life.plots[id])state.life.plots[id].watered=true;if(a==='harvest'&&MossSystems.harvest(state,id)){state.xp+=10;GameAudio.sfx('success');toast('Fresh ingredients picked! Visit the workbench to craft.');}plotMenu(id);}save();hud();
});
const journalButton=document.createElement('button');journalButton.className='wood';journalButton.dataset.life='journal';journalButton.textContent='Journal';document.querySelector('.hud-right').append(journalButton);
const saveButton=document.createElement('button');saveButton.id='save-status';saveButton.className='save-status';saveButton.dataset.life='saves';app.append(saveButton);
save();hud();void SaveStore.sync();setInterval(()=>void SaveStore.sync(),30000);addEventListener('online',()=>void SaveStore.sync(true));
